    private static int weight;
    private static int itemMass;
    private static boolean[] arr=new boolean[100];
    static{
        for(int i=0;i<100;i++)
            arr[i]=false;
    }
    public boolean isBalanced(){
        boolean isBalance=false;
        long pod1=itemMass, pod2=0;
        while(true){
            if(pod1>pod2){
                long nextMass=getMass(pod1-pod2);
                if(nextMass!=0){
                    pod2+=nextMass;
                } else {
                    break;
                }
            } else if(pod1<pod2){
                long nextMass=getMass(pod2-pod1);
                if(nextMass!=0){
                    pod1+=nextMass;
                } else {
                    break;
                }
            } else {
                isBalance=true;
                break;
            }
        }
        return isBalance;
    }
