    logBase = int((mass.bit_length() - 1) / (weight.bit_length() - 1))
    # Using bit_length for logarithm approximation
    # Since weight is an integer, we can use bit_length for logs base 2, but for arbitrary base, we approximate
    # For simplicity, we can use math.log
    import math
    logBase = int(math.log(mass, weight))
    sumTotal = (pow(weight, logBase + 1) - 1) // (weight - 1)
    if mass > sumTotal and not arr[logBase + 1]:
        result = pow(weight, logBase + 1)
        arr[logBase + 1] = True
    elif mass <= sumTotal and not arr[logBase]:
        result = pow(weight, logBase)
        arr[logBase] = True
    else:
